  };
  await saveEncounter(encounter);

  if (rapportDelta !== 0) {
    const party = await getParty(campaign.Id);
    if (party) {
      // V0.6 slice 7: no longer capped at 5 — a Rapport overflow beyond the track length is
      // banked until the next Make Camp rather than lost (see logic.ts's
      // applyPartyRapportAdvance/spendRapportForAid doc comments for the full mechanic).
      party.Rapport = Math.max(0, party.Rapport + rapportDelta);
      await saveParty(party);
    }
  }

  res.status(201).json({ encounter });
}));

// GM-only — ends an active Combat Encounter
combatRouter.post('/end', wrap<{ campaignId: string; encounterId: string }>(async (req, res) => {
  const campaign = await getCampaign(req.params.campaignId);
  if (!campaign) { res.status(404).json({ error: 'No such campaign.' }); return; }
  const membership = await membershipFor(campaign.Id, req.user!.id);
  if (!membership || membership.Role !== 'GM') { res.status(403).json({ error: 'Only the GM can end Combat.' }); return; }
  try {
    assertCampaignActive(campaign);
    assertPlayingPhase(campaign);
  } catch (err) {
    if (err instanceof CampaignArchivedError) { res.status(409).json({ error: err.message }); return; }
    if (err instanceof PlayingRequiredError) { res.status(409).json({ error: err.message }); return; }
    throw err;
  }

  const encounter = await getActiveEncounter(campaign.Id);
  if (!encounter) { res.status(404).json({ error: 'No active Combat to end.' }); return; }

  await repo.endEncounter(encounterId, campaignId);

  // Process PC participants
  const pcParticipants = encounter.Participants.filter(p => p.Kind === 'PC' && p.RefId);
  for (const participant of pcParticipants) {
    const sheet = await repo.getSheet(participant.RefId);
    if (sheet && sheet.Strain.some(s => s)) {
      const clearedSheet = { ...sheet, Strain: sheet.Strain.map(s => false) };
      await repo.saveSheet(clearedSheet, campaignId);
    }
  }

  // Add history entry
  encounter.History.unshift({
    Id: Date.now(),
    At: new Date().toISOString(),
    Text: `Combat ended at ${new Date().toISOString()}`
  });

  res.status(200).json({ encounter });
}));

// existing tests

// Test: End combat clears PC Strain and adds history
vi.mocked(repo.endEncounter).mockResolvedValue({
  Status: 'Ended',
  History: [{
    Id: 1,
    At: '2023-01-01T00:00:00Z',
    Text: 'Combat started'
  }]
});

vi.mocked(repo.getSheet).mockImplementation(async (refId) => {
  if (refId === 'PC1') return { Strain: [true, false] };
  if (refId === 'PC2') return { Strain: [false, false] };
  return null;
});

vi.mocked(repo.saveSheet).mockImplementation(async (sheet, campaignId) => {
  expect(sheet.Strain).toEqual([false, false]);
  return true;
});

const response = await request
  .post(`/campaigns/${campaignId}/combat/${encounterId}/end`)
  .set('Authorization', 'Bearer GM_TOKEN');

expect(response.status).toBe(200);
expect(response.body.encounter.Status).toBe('Ended');
expect(response.body.encounter.History).toEqual([{
  Id: 1,
  At: '2023-01-01T00:00:00Z',
  Text: `Combat ended at ${new Date().toISOString()}`
}, {
  Id: 2,
  At: '2023-01-01T00:00:00Z',
  Text: 'Combat started'
}]);

